void Solver::rephase() {
    // Reset the rephase counter for the next cycle
    rephases = 0;

    // Make the next rephase happen a bit earlier (more aggressive)
    threshold = static_cast<int>(threshold * 0.85);

    // Allow a larger number of rephases before the next trigger
    rephase_limit += 4096;

    // ---- Choose a new phase assignment strategy ----
    // 40% : keep the best phase seen so far
    // 30% : flip the best phase
    // 30% : assign a completely random phase
    int r = rand() % 100;
    if (r < 40) {
        for (int i = 1; i <= vars; ++i) saved[i] = local_best[i];
    } else if (r < 70) {
        for (int i = 1; i <= vars; ++i) saved[i] = -local_best[i];
    } else {
        for (int i = 1; i <= vars; ++i) saved[i] = (rand() & 1) ? 1 : -1;
    }

    // ---- Refresh the VSIDS heap ----
    // Re‑insert any variable that might have been removed from the heap
    for (int i = 1; i <= vars; ++i) {
        if (!vsids.inHeap(i)) vsids.insert(i);
    }
}
